class Solution:
    def eliminateMaximum(self, dist: list[int], speed: list[int]) -> int:
        n = len(dist)
        alive = [True] * n
        for minute in range(n):
            for i in range(n):
                if alive[i] and dist[i] <= speed[i] * minute:
                    return minute
            best = -1
            for i in range(n):
                if alive[i]:
                    if best == -1 or dist[i] * speed[best] < dist[best] * speed[i]:
                        best = i
            alive[best] = False
        return n

