class Solution:
    def eliminateMaximum(self, dist: list[int], speed: list[int]) -> int:
        deadlines = []
        for d, s in zip(dist, speed):
            deadlines.append((d + s - 1) // s)
        deadlines.sort()
        for minute, deadline in enumerate(deadlines):
            if deadline <= minute:
                return minute
        return len(dist)

