class Solution:
    def eliminateMaximum(self, dist: list[int], speed: list[int]) -> int:
        n = len(dist)
        buckets = [0] * (n + 1)
        for d, s in zip(dist, speed):
            deadline = (d + s - 1) // s
            buckets[min(deadline, n)] += 1
        arrived = 0
        for minute in range(n):
            arrived += buckets[minute]
            if arrived > minute:
                return minute
        return n

